// Export for ES6 modules (React)
export const ASIA_SEQUENTIAL_3STR = threeStrData;
export const ASIA_SEQUENTIAL_2STR = twoStrData;

// Metadata
export const ASIA_DATA_INFO = {
  threeStrCount: threeStrData.length,
  twoStrCount: twoStrData.length,

  source: "ASIA data hsr.csv",
  extractedDate: "2024-12-04",
};
// Helper: Get only recent patches (default: last 2 patches)
export function getRecentPatchData(dataset, lookbackPatches = 2) {
  if (!dataset || !dataset.length) return [];

  // Find all unique patches and sort them
  const patches = [...new Set(dataset.map((d) => d.patch))].sort((a, b) => {
    const [aMajor, aMinor] = a.split(".").map(Number);
    const [bMajor, bMinor] = b.split(".").map(Number);
    return aMajor * 10 + aMinor - (bMajor * 10 + bMinor);
  });

  // Get the most recent N patches
  const recentPatches = patches.slice(-lookbackPatches);

  // Filter dataset
  return dataset.filter((d) => recentPatches.includes(d.patch));
}

// Helper: Get just the rolls (backward compatible)
export function getRolls(dataset, rollKey = "3str") {
  return dataset.map((d) => d[rollKey]).filter(Boolean);
}

// Helper: Get data by specific patches
export function getDataByPatches(dataset, patchList) {
  return dataset.filter((d) => patchList.includes(d.patch));
}

// Helper: Get patch statistics
export function getPatchStats(dataset) {
  const patchCounts = {};
  dataset.forEach((d) => {
    patchCounts[d.patch] = (patchCounts[d.patch] || 0) + 1;
  });

  return Object.entries(patchCounts)
    .map(([patch, count]) => ({ patch, count }))
    .sort((a, b) => {
      const [aMajor, aMinor] = a.patch.split(".").map(Number);
      const [bMajor, bMinor] = b.patch.split(".").map(Number);
      return aMajor * 10 + aMinor - (bMajor * 10 + bMinor);
    });
}

// Enhanced metadata
export const ASIA_PATCH_INFO = getPatchStats(threeStrData);
// Backward compatible: default to recent 2 patches
export const ASIA_SEQUENTIAL_3STR_RECENT = getRolls(
  getRecentPatchData(threeStrData, 2),
  "3str"
);

export const ASIA_SEQUENTIAL_2STR_RECENT = getRolls(
  getRecentPatchData(twoStrData, 2),
  "2str"
);

// Full historical (for testing/comparison)
export const ASIA_SEQUENTIAL_3STR_ALL = getRolls(threeStrData, "3str");
export const ASIA_SEQUENTIAL_2STR_ALL = getRolls(twoStrData, "2str");
